export function marciaStaticListings(publicBase = 'https://condominiosnapraia.com.br', publicPrefix = '') {
  const prefix = publicPrefix || '/corretor/marcia-anzolin';
  return MARCIA_STATIC_PROPERTIES.map((item, index) => ({
    id: item.id,
    slug: item.slug,
    url: `${publicBase}${prefix}/imovel/${encodeURIComponent(item.slug)}/`,
    title: item.title,
    description: item.description,
    type: item.type,
    category: /terreno|lote/i.test(item.type) ? 'terreno-condominio' : (/apartamento|loft|cobertura|studio/i.test(item.type) ? 'apartamento' : 'casa-condominio'),
    city: item.city,
    neighborhood: item.neighborhood,
    price: item.price,
    bedrooms: item.bedrooms,
    suites: item.suites,
    bathrooms: item.bathrooms,
    parking: item.parking,
    area: item.area,
    photo: item.photo,
    featured: Boolean(item.featured),
    status: item.status,
    code: item.code,
    condo: item.condoName ? { id: item.condoName.toLowerCase().replace(/[^a-z0-9]+/g, '-'), name: item.condoName, city: item.city } : null,
    displayOrder: index,
  }));
}

export function marciaStaticProperty(slug) {
  return MARCIA_STATIC_PROPERTIES.find((item) => item.slug === slug) || null;
}
